pub(super) fn evidence_definition_by_id(evidence_id: &str) -> Option<EvidenceDefinition> {
    EVIDENCE_DEFINITIONS
        .iter()
        .copied()
        .find(|definition| definition.evidence_id == evidence_id)
}

pub(super) fn evidence_definition_by_route(route: &str) -> Option<EvidenceDefinition> {
    EVIDENCE_DEFINITIONS
        .iter()
        .copied()
        .find(|definition| definition.route_selector == route)
}
